#include <bits/stdc++.h>
using namespace std;

typedef pair<int,int> point;

const int MAXR = 11;
const int MAXN = 1000;
const int MAXM = 100100;
const int INF = (1<<29);

int edges[2*MAXM], flowValues[2*MAXM], capacity[2*MAXM], nextEdge[2*MAXM];
int head[MAXN], current[MAXN], level[MAXN], queueArr[MAXN];
int totalEdges, totalNodes, sourceNode, sinkNode, frontIdx, rearIdx;

void setupFlow(int nodes, int sNode, int tNode) {
    totalNodes = nodes; sourceNode = sNode; sinkNode = tNode; totalEdges=2;
    for (int i=0; i<=totalNodes; i++) head[i]=0;
}
void addEdge(int u, int v, int capVal) {
    edges[totalEdges]=v; flowValues[totalEdges]=0; capacity[totalEdges]=capVal; nextEdge[totalEdges]=head[u]; head[u]=totalEdges++;
    edges[totalEdges]=u; flowValues[totalEdges]=0; capacity[totalEdges]=0; nextEdge[totalEdges]=head[v]; head[v]=totalEdges++;
}
bool buildLevelGraph() {
    for (int i=0; i<=totalNodes; i++) level[i]=0;
    frontIdx=rearIdx=0;
    queueArr[frontIdx++]=sourceNode;
    level[sourceNode]=1;
    while (rearIdx<frontIdx && !level[sinkNode]) {
        int u=queueArr[rearIdx++];
        for (int e=head[u]; e; e=nextEdge[e]) {
            int v=edges[e];
            if (!level[v] && flowValues[e]<capacity[e]) {
                level[v]=level[u]+1;
                queueArr[frontIdx++]=v;
            }
        }
    }
    return level[sinkNode]!=0;
}
int sendFlow(int u, int flowAmt) {
    if (u==sinkNode) return flowAmt;
    for (int &e=current[u], f=0; e; e= current[u]=nextEdge[e]) {
        int v=edges[e];
        if (level[u]<level[v] && flowValues[e]<capacity[e] && (f=sendFlow(v, min(flowAmt, capacity[e]-flowValues[e])))) {
            flowValues[e]+=f;
            flowValues[e^1]-=f;
            return f;
        }
    }
    return 0;
}
int computeMaxFlow() {
    int totalFlow=0, f;
    while (buildLevelGraph()) {
        for (int i=0; i<=totalNodes; i++) current[i]=head[i];
        while ((f=sendFlow(sourceNode, INF))) totalFlow+=f;
    }
    return totalFlow;
}

int R;
string gridA[MAXR], gridB[MAXR];

int dirI[] = {0,1,0,-1};
int dirJ[] = {1,0,-1,0};

bool canProceed(int i, int j) {
    return (i>=0 && j>=0 && i<R && j<R && gridA[i][j]!='Y' && gridA[i][j]!='Z');
}

int timeMatrix[2][MAXR][MAXR];

void runBFS(int i, int j, int c) {
    for (int k=0; k<R; k++) {
        for (int l=0; l<R; l++) {
            timeMatrix[c][k][l]=0;
        }
    }
    timeMatrix[c][i][j]=1;
    queue<point> q;
    q.push({i,j});
    while (!q.empty()) {
        auto [x,y]=q.front(); q.pop();
        if (c==1 && (timeMatrix[0][x][y] && timeMatrix[0][x][y]<=timeMatrix[1][x][y])) continue;
        for (int k=0; k<4; k++) {
            int ni=x+dirI[k], nj=y+dirJ[k];
            if (canProceed(ni,nj) && !timeMatrix[c][ni][nj]) {
                timeMatrix[c][ni][nj]=timeMatrix[c][x][y]+1;
                q.push({ni,nj});
            }
        }
    }
}

int nodeIDMap[2][MAXR][MAXR];

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int T; cin >> R >> T;
    int zi=0, zj=0;
    int totalNodes=0, start=0, end=0;
    for (int i=0; i<R; i++) {
        cin >> gridA[i];
        for (int j=0; j<R; j++) {
            if (gridA[i][j]=='Z') {
                zi=i; zj=j;
            } else if (gridA[i][j]!='Y') {
                totalNodes++;
                nodeIDMap[0][i][j]=totalNodes;
            }
        }
    }
    for (int i=0; i<R; i++) {
        cin >> gridB[i];
        for (int j=0; j<R; j++) {
            if (gridB[i][j]!='Y' && gridB[i][j]!='Z') {
                totalNodes++;
                nodeIDMap[1][i][j]=totalNodes;
            }
        }
    }
    totalNodes++;
    start=0; end=totalNodes;
    setupFlow(totalNodes, start, end);
    for (int i=0; i<R; i++) {
        for (int j=0; j<R; j++) {
            if (gridA[i][j]!='Z' && gridA[i][j]!='Y') {
                addEdge(start, nodeIDMap[0][i][j], gridA[i][j]-'0');
                addEdge(nodeIDMap[1][i][j], end, gridB[i][j]-'0');
            }
        }
    }
    runBFS(zi, zj, 0);
    for (int i=0; i<R; i++) {
        for (int j=0; j<R; j++) {
            if (gridA[i][j]>'0' && gridA[i][j]<='9') {
                runBFS(i, j, 1);
                for (int ii=0; ii<R; ii++) {
                    for (int jj=0; jj<R; jj++) {
                        if (gridB[ii][jj]>'0' && gridB[ii][jj]<='9') {
                            if (timeMatrix[1][ii][jj] && (!timeMatrix[0][ii][jj] || timeMatrix[0][ii][jj]>=timeMatrix[1][ii][jj]) && timeMatrix[1][ii][jj]-1<=T) {
                                addEdge(nodeIDMap[0][i][j], nodeIDMap[1][ii][jj], INF);
                            }
                        }
                    }
                }
            }
        }
    }
    cout << computeMaxFlow() << '\n';
}
